/** Bounded Modrinth/import IO. Every mutation is staged for the launcher, never applied to loaded jars. */
public final class ModLibraryService {
 public record Installed(String id,String name,String version,String filename,String folder,boolean enabled,boolean mutable,byte[] icon){}
 public record Project(String id,String name,String description,String kind,String iconUrl,int downloads,String provider){public Project(String id,String name,String description,String kind,String iconUrl,int downloads){this(id,name,description,kind,iconUrl,downloads,"modrinth");}}
 public record Search(List<Project> projects,int total,int offset){}
 private record Package(String folder,String filename,Path staged,String hash,JsonObject metadata,String modId){}
 private static final String API="https://api.modrinth.com/v2";
 private static final ThreadPoolExecutor IO=new ThreadPoolExecutor(1,1,0,TimeUnit.SECONDS,new ArrayBlockingQueue<>(4),r->{var t=new Thread(r,"Votex addon library");t.setDaemon(true);return t;},new ThreadPoolExecutor.AbortPolicy());
 private static final ThreadPoolExecutor ICON_IO=new ThreadPoolExecutor(2,2,0,TimeUnit.SECONDS,new ArrayBlockingQueue<>(32),r->{var t=new Thread(r,"Votex catalogue icons");t.setDaemon(true);return t;},new ThreadPoolExecutor.AbortPolicy());
 private static final HttpClient HTTP=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(15)).followRedirects(HttpClient.Redirect.NEVER).build();
 public record Transfer(String detail,long completed,long total){}
 private static final ThreadLocal<java.util.function.Consumer<Transfer>> TRANSFER=new ThreadLocal<>();
 public static <T> T withProgress(java.util.function.Consumer<Transfer> listener,Callable<T> work)throws Exception{var previous=TRANSFER.get();TRANSFER.set(listener);try{return work.call();}finally{if(previous==null)TRANSFER.remove();else TRANSFER.set(previous);}}
 private static void progress(String detail,long completed,long total){var listener=TRANSFER.get();if(listener!=null)listener.accept(new Transfer(detail,completed,total));}
 private ModLibraryService(){}
 public static <T> CompletableFuture<T> async(Callable<T> work){return submit(work,IO);}
 public static CompletableFuture<byte[]> iconAsync(String url){return submit(()->icon(url),ICON_IO);}
 private static <T> CompletableFuture<T> submit(Callable<T> work,Executor executor){try{return CompletableFuture.supplyAsync(()->{try{return work.call();}catch(Exception e){throw new CompletionException(e);}},executor);}catch(RejectedExecutionException busy){return CompletableFuture.failedFuture(new IOException("Bitte laufende Downloads abwarten"));}}
 public static List<Installed> installed(Path root)throws Exception{var found=new ArrayList<Installed>();var visited=new HashSet<String>();Path mods=checked(root,"mods").toAbsolutePath().normalize();for(var container:FabricLoader.getInstance().getAllMods()){if(container.getContainingMod().isPresent())continue;var m=container.getMetadata();String filename="";for(var origin:container.getOrigin().getPaths())if(origin.toAbsolutePath().normalize().getParent()!=null&&origin.toAbsolutePath().normalize().getParent().equals(mods)){filename=origin.getFileName().toString();break;}boolean mutable=!filename.isEmpty()&&!Set.of("fabricloader","minecraft","java","votex_client","fabric-api").contains(m.getId());byte[] icon=null;var location=m.getIconPath(64);if(location.isPresent()){var path=container.findPath(location.get());if(path.isPresent())try{byte[] bytes=bounded(Files.newInputStream(path.get()),512*1024);icon=IconImage.thumbnail(bytes);}catch(Exception ignored){}}found.add(new Installed(m.getId(),m.getName(),m.getVersion().getFriendlyString(),filename,"mods",true,mutable,icon));if(!filename.isEmpty())visited.add(filename);}
  if(Files.isDirectory(mods))try(var stream=Files.list(mods)){for(var path:stream.limit(500).toList()){String file=path.getFileName().toString();if(file.endsWith(".jar.disabled")&&!visited.contains(file)){var meta=jar(path);found.add(new Installed(string(meta,"id",file),string(meta,"name",file),string(meta,"version","?"),file,"mods",false,true,jarIcon(path,meta)));}}}
  for(String folder:List.of("shaderpacks","resourcepacks")){Path dir=checked(root,folder);if(Files.isDirectory(dir))try(var stream=Files.list(dir)){for(var path:stream.limit(300).toList())if(Files.isRegularFile(path)&&path.getFileName().toString().endsWith(".zip")){String filename=path.getFileName().toString();found.add(new Installed(filename,filename,"ZIP",filename,folder,true,true,null));}}}
  found.sort(Comparator.comparing(Installed::name,String.CASE_INSENSITIVE_ORDER));return List.copyOf(found);
 }
 public static Search search(String query,String kind,int offset)throws Exception{return search(query,kind,offset,20);}
 public static Search search(String provider,String query,String kind,int offset,int limit)throws Exception{if(provider.equals("curseforge"))return CurseForgeClient.search(query,kind,offset,limit);if(!provider.equals("modrinth"))throw new IOException("Unbekannte Mod-Quelle");return search(query,kind,offset,limit);}
 public static Search search(String query,String kind,int offset,int limit)throws Exception{AddonRules.folder(kind);JsonArray facets=new JsonArray();facets.add(array("project_type:"+kind));facets.add(array("versions:26.2"));if(kind.equals("mod"))facets.add(array("categories:fabric"));if(kind.equals("shader"))facets.add(array("categories:iris"));String path="/search?query="+encode(query.strip())+"&facets="+encode(facets.toString())+"&index=relevance&limit="+Math.clamp(limit,1,20)+"&offset="+Math.clamp(offset,0,10000);var body=get(path).getAsJsonObject();var result=new ArrayList<Project>();for(var item:body.getAsJsonArray("hits")){var hit=item.getAsJsonObject();result.add(new Project(AddonRules.reference(hit.get("project_id").getAsString()),string(hit,"title","Modrinth"),string(hit,"description",""),kind,string(hit,"icon_url",""),hit.has("downloads")?hit.get("downloads").getAsInt():0));}return new Search(List.copyOf(result),body.get("total_hits").getAsInt(),offset);}
 public static byte[] icon(String url)throws Exception{if(url==null||url.isEmpty())return null;if(URI.create(url).getHost()!=null&&URI.create(url).getHost().equals("media.forgecdn.net"))return CurseForgeClient.icon(url);byte[] bytes=fetch(AddonRules.cdn(url),512*1024);return IconImage.thumbnail(bytes);}
 public static int stageProject(Path root,Project project)throws Exception{if(project.provider().equals("curseforge"))return stageCurseForge(root,project);if(!project.provider().equals("modrinth"))throw new IOException("Unbekannte Mod-Quelle");var versions=dev.votex.addons.ModrinthGraph.resolve(project.id(),project.kind(),installedMetadata(root),new dev.votex.addons.ModrinthGraph.Catalog(){public JsonArray versions(String id,String kind)throws Exception{return versionList(id,kind);}public JsonObject version(String id)throws Exception{return get("/version/"+AddonRules.reference(id)).getAsJsonObject();}});
  Path stage=staging(root);var packages=new ArrayList<Package>();long total=0;for(var version:versions.values()){var files=version.getAsJsonArray("files");JsonObject file=null;for(var raw:files)if(raw.getAsJsonObject().has("primary")&&raw.getAsJsonObject().get("primary").getAsBoolean()){file=raw.getAsJsonObject();break;}if(file==null&&files.size()>0)file=files.get(0).getAsJsonObject();if(file==null)throw new IOException("Keine herunterladbare Datei");String kind=version.get("votex_kind").getAsString(),filename=AddonRules.filename(file.get("filename").getAsString());progress("Datei prüfen · "+filename,0,0);if(!(filename.endsWith(kind.equals("mod")?".jar":".zip")))throw new IOException("Falsches Dateiformat");String hash=AddonRules.hash(file.getAsJsonObject("hashes").get("sha512").getAsString());long size=file.get("size").getAsLong();if(size<1||size>AddonRules.MAX_FILE||(total+=size)>AddonRules.MAX_TOTAL)throw new IOException("Erweiterung überschreitet das Größenlimit");Path target=stage.resolve(hash+".bin");if(!Files.exists(target)||!sha512(target).equals(hash)){byte[] bytes=fetch(AddonRules.cdn(file.get("url").getAsString()),AddonRules.MAX_FILE);if(bytes.length!=size||!HexFormat.of().formatHex(MessageDigest.getInstance("SHA-512").digest(bytes)).equals(hash))throw new IOException("Download-Prüfsumme stimmt nicht überein");writeBytes(target,bytes);}String modId="";if(kind.equals("mod")){var meta=jar(target);validateRuntime(meta);modId=meta.get("id").getAsString();}else validateZip(target,kind);JsonObject metadata=version.deepCopy();metadata.remove("votex_kind");metadata.addProperty("filename",filename);packages.add(new Package(AddonRules.folder(kind),filename,target,hash,metadata,modId));}
  return queuePackages(root,packages);
 }
 private static int stageCurseForge(Path root,Project project)throws Exception{var plan=CurseForgeClient.resolve(project);var planned=new HashSet<Long>();for(var item:plan)planned.add(item.project().id());var existing=installedMetadata(root);for(var item:plan)for(long incompatible:item.file().incompatible())for(var raw:existing){var old=raw.getAsJsonObject();if(string(old,"project_id","").equals("cf-"+incompatible)&&!planned.contains(incompatible))throw new IOException("CurseForge meldet eine inkompatible bereits installierte Erweiterung");}Path stage=staging(root);var packages=new ArrayList<Package>();for(var item:plan){progress("Datei laden und prüfen · "+item.file().name(),0,0);byte[] bytes=CurseForgeClient.download(item.file());String hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-512").digest(bytes));Path target=stage.resolve(hash+".bin");writeBytes(target,bytes);String modId="";if(item.project().kind().equals("mod")){var meta=jar(target);validateRuntime(meta);modId=meta.get("id").getAsString();}else validateZip(target,item.project().kind());JsonObject metadata=new JsonObject();metadata.addProperty("project_id","cf-"+item.project().id());metadata.addProperty("id","cf-"+item.file().id());metadata.addProperty("name",item.project().name());metadata.addProperty("version_number",item.file().display());metadata.addProperty("provider","curseforge");metadata.addProperty("filename",item.file().name());metadata.addProperty("sha1",item.file().sha1());metadata.addProperty("website",item.project().website());metadata.addProperty("allowModDistribution",item.project().distributionAllowed());packages.add(new Package(AddonRules.folder(item.project().kind()),item.file().name(),target,hash,metadata,modId));}return queuePackages(root,packages);}
 private static JsonArray versionList(String id,String kind)throws Exception{String loaders=kind.equals("mod")?"&loaders="+encode("[\"fabric\"]"):kind.equals("shader")?"&loaders="+encode("[\"iris\"]"):"";return get("/project/"+AddonRules.reference(id)+"/version?game_versions="+encode("[\"26.2\"]")+loaders).getAsJsonArray();}
 public static int importFile(Path root,Path source,String kind)throws Exception{AddonRules.folder(kind);if(!Files.isRegularFile(source)||Files.isSymbolicLink(source)||Files.size(source)>AddonRules.MAX_FILE)throw new IOException("Datei fehlt, ist verknüpft oder zu groß");String filename=AddonRules.filename(source.getFileName().toString());if(!filename.endsWith(kind.equals("mod")?".jar":".zip"))throw new IOException("Bitte eine "+(kind.equals("mod")?"JAR":"ZIP")+" auswählen");String hash=sha512(source);Path target=staging(root).resolve(hash+".bin");writeBytes(target,bounded(Files.newInputStream(source),AddonRules.MAX_FILE));if(!sha512(target).equals(hash))throw new IOException("Die Quelldatei wurde während des Imports geändert");String modId="";JsonObject metadata=new JsonObject();if(kind.equals("mod")){var meta=jar(target);validateRuntime(meta);modId=meta.get("id").getAsString();metadata.addProperty("name",string(meta,"name",modId));metadata.addProperty("version_number",string(meta,"version","?"));metadata.addProperty("project_id","local-"+modId);}else{validateZip(target,kind);metadata.addProperty("project_id","local-"+hash.substring(0,16));}metadata.addProperty("id","local-"+hash.substring(0,16));metadata.addProperty("filename",filename);return queuePackages(root,List.of(new Package(AddonRules.folder(kind),filename,target,hash,metadata,modId)));}
 private static synchronized int queuePackages(Path root,List<Package> packages)throws Exception{var changes=readQueue(root);validateDependencies(root,packages,changes);var installed=installed(root);JsonArray metadata=installedMetadata(root);int count=0;for(var p:packages){Path existingFile=checked(root,p.folder()+"/"+p.filename());if(Files.isRegularFile(existingFile)&&sha512(existingFile).equals(p.hash()))continue;JsonObject action=new JsonObject();action.addProperty("kind","install");action.addProperty("folder",p.folder());action.addProperty("filename",p.filename());action.addProperty("staged",p.hash()+".bin");action.addProperty("sha512",p.hash());action.add("metadata",p.metadata());JsonArray replaces=new JsonArray();for(var old:installed)if(old.folder().equals(p.folder())&&(!p.modId().isEmpty()&&old.id().equals(p.modId())||sameFile(old.filename(),p.filename()))&&!old.filename().isEmpty()){if(!old.mutable()&&!old.id().equals("fabric-api"))throw new IOException("Diese zentrale Client-Komponente wird vom Launcher verwaltet");replaces.add(old.filename());}for(var raw:metadata){var old=raw.getAsJsonObject();if(string(old,"project_id","").equals(string(p.metadata(),"project_id",""))){String name=string(old,"filename","");if(!name.isEmpty()&&!contains(replaces,name))replaces.add(AddonRules.filename(name));}}if(Files.isRegularFile(existingFile)&&!contains(replaces,p.filename()))replaces.add(p.filename());JsonObject replaceHashes=new JsonObject();var iterator=replaces.iterator();while(iterator.hasNext()){String oldName=iterator.next().getAsString();Path oldPath=checked(root,p.folder()+"/"+oldName);if(!Files.exists(oldPath)){iterator.remove();continue;}if(Files.isSymbolicLink(oldPath))throw new IOException("Verknüpfte Mod-Dateien können nicht ersetzt werden");replaceHashes.addProperty(oldName,sha512(oldPath));}action.add("replaceHashes",replaceHashes);action.add("replaces",replaces);changes.asList().removeIf(raw->{var old=raw.getAsJsonObject();return string(old,"folder","").equals(p.folder())&&contains(replaces,string(old,"filename",""));});upsert(changes,action);count++;}saveQueue(root,changes);return count;}
 public static synchronized void change(Path root,Installed item,String kind)throws Exception{if(!item.mutable()||item.filename().isEmpty()||!Set.of("disable","enable","remove").contains(kind))throw new IOException("Diese Komponente kann hier nicht geändert werden");var changes=readQueue(root);if(item.folder().equals("mods")&&!kind.equals("enable"))for(var container:FabricLoader.getInstance().getAllMods())if(!container.getMetadata().getId().equals(item.id()))for(var dependency:container.getMetadata().getDependencies())if(dependency.getKind()==ModDependency.Kind.DEPENDS&&dependency.getModId().equals(item.id())){String consumer=container.getMetadata().getName();boolean queued=changes.asList().stream().anyMatch(raw->string(raw.getAsJsonObject(),"filename","").equals(container.getOrigin().getPaths().getFirst().getFileName().toString())&&!string(raw.getAsJsonObject(),"kind","").equals("install"));if(!queued)throw new IOException(consumer+" benötigt diese Mod. Zuerst die abhängige Mod deaktivieren.");}JsonObject action=new JsonObject();action.addProperty("kind",kind);action.addProperty("folder",item.folder());action.addProperty("filename",AddonRules.filename(item.filename()));action.addProperty("sourceSha512",sha512(checked(root,item.folder()+"/"+item.filename())));upsert(changes,action);saveQueue(root,changes);}
 public static synchronized void cancel(Path root,String folder,String filename)throws Exception{var queue=readQueue(root);queue.asList().removeIf(raw->sameFile(string(raw.getAsJsonObject(),"filename",""),filename)&&string(raw.getAsJsonObject(),"folder","").equals(folder));saveQueue(root,queue);}
 public static JsonArray readQueue(Path root)throws Exception{Path path=checked(root,"config/votex/addon-queue.json");if(!Files.exists(path))return new JsonArray();if(Files.size(path)>512*1024)throw new IOException("Änderungsliste ist zu groß");var body=JsonParser.parseString(Files.readString(path)).getAsJsonObject();if(body.get("schemaVersion").getAsInt()!=1)throw new IOException("Unbekannte Änderungsliste");return body.getAsJsonArray("actions");}
 private static void saveQueue(Path root,JsonArray actions)throws Exception{if(actions.size()>100)throw new IOException("Maximal 100 vorgemerkte Änderungen");JsonObject body=new JsonObject();body.addProperty("schemaVersion",1);body.add("actions",actions);byte[] bytes=AtomicJson.GSON.toJson(body).getBytes(java.nio.charset.StandardCharsets.UTF_8);if(bytes.length>512*1024)throw new IOException("Änderungsliste ist zu groß");AtomicJson.write(checked(root,"config/votex/addon-queue.json"),body);}
 private static void upsert(JsonArray queue,JsonObject action){queue.asList().removeIf(raw->{var old=raw.getAsJsonObject();return string(old,"folder","").equals(string(action,"folder",""))&&(sameFile(string(old,"filename",""),string(action,"filename",""))||old.has("metadata")&&action.has("metadata")&&string(old.getAsJsonObject("metadata"),"project_id","").equals(string(action.getAsJsonObject("metadata"),"project_id","")));});queue.add(action);}
 private static JsonArray installedMetadata(Path root)throws Exception{Path path=checked(root,"mods/installed.json");if(!Files.exists(path))return new JsonArray();if(Files.size(path)>4*1024*1024)throw new IOException("Mod-Metadaten sind zu groß");return JsonParser.parseString(Files.readString(path)).getAsJsonArray();}
 private static Path staging(Path root)throws Exception{Path path=checked(root,"config/votex/addon-staging");Files.createDirectories(path);if(!path.toRealPath().startsWith(root.toRealPath()))throw new IOException("Staging-Pfad verlässt das Profil");return path;}
 private static JsonObject jar(Path path)throws Exception{try(var zip=new ZipFile(path.toFile())){var entry=zip.getEntry("fabric.mod.json");if(entry==null)throw new IOException("Keine Fabric-Mod (fabric.mod.json fehlt)");try(var stream=zip.getInputStream(entry)){var metadata=JsonParser.parseString(new String(bounded(stream,128*1024),java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();if(!string(metadata,"id","").matches("[a-z][a-z0-9_-]{1,63}"))throw new IOException("Ungültige Mod-Kennung");return metadata;}}}
 private static byte[] jarIcon(Path path,JsonObject metadata){try(var zip=new ZipFile(path.toFile())){if(!metadata.has("icon"))return null;var icon=metadata.get("icon");String name=icon.isJsonPrimitive()?icon.getAsString():icon.getAsJsonObject().entrySet().stream().findFirst().orElseThrow().getValue().getAsString();var entry=zip.getEntry(name);if(entry==null)return null;byte[] bytes=bounded(zip.getInputStream(entry),512*1024);return IconImage.thumbnail(bytes);}catch(Exception ignored){return null;}}
 private static void validateRuntime(JsonObject metadata)throws Exception{if(Set.of("minecraft","java","fabricloader","votex_client").contains(string(metadata,"id","")))throw new IOException("Diese zentrale Client-Komponente wird vom Launcher verwaltet");if(string(metadata,"environment","*").equals("server"))throw new IOException("Diese Mod ist ausschließlich für einen Server");if(!metadata.has("depends"))return;var dependencies=metadata.getAsJsonObject("depends");for(String id:List.of("minecraft","java","fabricloader"))if(dependencies.has(id)){var container=FabricLoader.getInstance().getModContainer(id).orElseThrow();JsonElement raw=dependencies.get(id);boolean matches=false;if(raw.isJsonArray())for(var value:raw.getAsJsonArray())matches|=VersionPredicate.parse(value.getAsString()).test(container.getMetadata().getVersion());else matches=VersionPredicate.parse(raw.getAsString()).test(container.getMetadata().getVersion());if(!matches)throw new IOException("Nicht kompatibel mit der laufenden "+id+"-Version");}}
 private static void validateDependencies(Path root,List<Package> packages,JsonArray changes)throws Exception{var versions=new HashMap<String,Version>();for(var c:FabricLoader.getInstance().getAllMods()){versions.put(c.getMetadata().getId(),c.getMetadata().getVersion());for(String alias:c.getMetadata().getProvides())versions.put(alias,c.getMetadata().getVersion());}var candidates=new ArrayList<JsonObject>();var localInstalled=installed(root);for(var raw:changes){var action=raw.getAsJsonObject();if(Set.of("disable","remove").contains(string(action,"kind",""))&&string(action,"folder","").equals("mods"))for(var old:localInstalled)if(old.filename().equals(string(action,"filename","")))versions.remove(old.id());}for(var raw:changes){var a=raw.getAsJsonObject();if(string(a,"kind","").equals("install")&&string(a,"folder","").equals("mods")){Path file=staging(root).resolve(AddonRules.hash(string(a,"sha512",""))+".bin");if(Files.exists(file)){var meta=jar(file);versions.put(meta.get("id").getAsString(),Version.parse(meta.get("version").getAsString()));}}}for(var p:packages)if(p.folder().equals("mods")){var meta=jar(p.staged());versions.put(meta.get("id").getAsString(),Version.parse(meta.get("version").getAsString()));candidates.add(meta);}for(var c:FabricLoader.getInstance().getAllMods())if(packages.stream().noneMatch(p->p.modId().equals(c.getMetadata().getId())))for(var dep:c.getMetadata().getDependencies())if(dep.getKind()==ModDependency.Kind.DEPENDS&&versions.containsKey(dep.getModId())&&!dep.matches(versions.get(dep.getModId())))throw new IOException("Die neue Version von "+dep.getModId()+" passt nicht zu "+c.getMetadata().getName());for(var meta:candidates)if(meta.has("depends"))for(var dep:meta.getAsJsonObject("depends").entrySet()){Version version=versions.get(dep.getKey());if(version==null)throw new IOException("Fehlende Abhängigkeit: "+dep.getKey()+". Bitte zuerst über Modrinth hinzufügen.");boolean valid=false;var raw=dep.getValue();if(raw.isJsonArray())for(var predicate:raw.getAsJsonArray())valid|=VersionPredicate.parse(predicate.getAsString()).test(version);else valid=VersionPredicate.parse(raw.getAsString()).test(version);if(!valid)throw new IOException("Nicht passende Abhängigkeit: "+dep.getKey()+" für "+string(meta,"name",meta.get("id").getAsString()));}}
 private static Path checked(Path root,String relative)throws IOException{Path base=root.toAbsolutePath().normalize(),path=base.resolve(relative).normalize();if(!path.startsWith(base))throw new IOException("Erweiterungspfad verlässt das Profil");Path existing=path;while(existing!=null&&!Files.exists(existing))existing=existing.getParent();if(existing==null||!existing.toRealPath().startsWith(base.toRealPath()))throw new IOException("Verknüpfter Erweiterungspfad verlässt das Profil");return path;}
 private static void writeBytes(Path path,byte[] bytes)throws Exception{Path temporary=path.resolveSibling(path.getFileName()+".tmp-"+UUID.randomUUID());try{Files.write(temporary,bytes,StandardOpenOption.CREATE_NEW);try{Files.move(temporary,path,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException ignored){Files.move(temporary,path,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(temporary);}}
 private static void validateZip(Path path,String kind)throws Exception{try(var zip=new ZipFile(path.toFile())){if(kind.equals("resourcepack")&&zip.getEntry("pack.mcmeta")==null)throw new IOException("Ressourcenpaket enthält keine pack.mcmeta");if(kind.equals("shader")){boolean shader=false;var entries=zip.entries();int seen=0;while(entries.hasMoreElements()&&seen++<10000){String name=entries.nextElement().getName();if(name.startsWith("shaders/")){shader=true;break;}}if(!shader)throw new IOException("Shader-ZIP enthält keinen shaders-Ordner");}}}
 private static JsonElement get(String path)throws Exception{return JsonParser.parseString(new String(fetch(URI.create(API+path),4*1024*1024),java.nio.charset.StandardCharsets.UTF_8));}
 private static byte[] fetch(URI uri,long max)throws Exception{var request=HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(35)).header("User-Agent","VotexClient/0.4.1 (https://votex-client-project.adoredpeach257.chatgpt.site)").GET().build();var response=HTTP.send(request,HttpResponse.BodyHandlers.ofInputStream());if(response.statusCode()!=200){response.body().close();throw new IOException("Modrinth HTTP "+response.statusCode());}if(response.headers().firstValueAsLong("Content-Length").orElse(0)>max){response.body().close();throw new IOException("Antwort zu groß");}String phase="api.modrinth.com".equals(uri.getHost())?"Metadaten laden":"Datei herunterladen";long size=response.headers().firstValueAsLong("Content-Length").orElse(0);progress(phase,0,size);try(var stream=response.body();var bytes=new ByteArrayOutputStream()){byte[] buffer=new byte[16384];int count;long total=0,last=0;while((count=stream.read(buffer))!=-1){if((total+=count)>max)throw new IOException("Datei überschreitet das Größenlimit");bytes.write(buffer,0,count);long now=System.nanoTime();if(now-last>80_000_000L){progress(phase,total,size);last=now;}}progress("Datei und Prüfsumme prüfen",0,0);return bytes.toByteArray();}}
 private static byte[] bounded(InputStream stream,long max)throws Exception{try(stream;var bytes=new ByteArrayOutputStream()){byte[] buffer=new byte[16384];int count;long total=0;while((count=stream.read(buffer))!=-1){if((total+=count)>max)throw new IOException("Datei überschreitet das Größenlimit");bytes.write(buffer,0,count);}return bytes.toByteArray();}}
 private static String sha512(Path path)throws Exception{if(Files.size(path)>AddonRules.MAX_FILE)throw new IOException("Datei ist zu groß");var digest=MessageDigest.getInstance("SHA-512");try(var in=Files.newInputStream(path)){byte[] buffer=new byte[65536];int count;long total=0;while((count=in.read(buffer))!=-1){if((total+=count)>AddonRules.MAX_FILE)throw new IOException("Datei ist zu groß");digest.update(buffer,0,count);}}return HexFormat.of().formatHex(digest.digest());}
 private static boolean references(JsonObject dependency,JsonObject version){return !string(dependency,"version_id","").isEmpty()&&string(dependency,"version_id","").equals(string(version,"id",""))||!string(dependency,"project_id","").isEmpty()&&string(dependency,"project_id","").equals(string(version,"project_id",""));}
 private static boolean contains(JsonArray values,String value){for(var item:values)if(sameFile(item.getAsString(),value))return true;return false;}
 private static boolean sameFile(String first,String second){return first.toUpperCase(Locale.ROOT).equals(second.toUpperCase(Locale.ROOT));}
 private static JsonArray array(String value){JsonArray a=new JsonArray();a.add(value);return a;}
 private static String encode(String value){return URLEncoder.encode(value,java.nio.charset.StandardCharsets.UTF_8);}
 private static String string(JsonObject o,String key,String fallback){var v=o.get(key);return v==null||v.isJsonNull()?fallback:v.getAsString();}
}
